mapper.select:
select org.*
from bus_rel_org org
where 1=1

    and org.org_name like concat(concat('%',#{orgName}),'%')


    and org.approval_status like #{approvalStatus}


    and org.identify_type like #{identifyType}


    and org.TRANSACTION_DEP like #{transactionDep}


    and org.domestic_or_foreign like #{domesticOrForeign}


    and org.effect_relation like #{effectRelation}


    and DATE_FORMAT(org.CREATED_TIME_, '%Y-%m-%d') like DATE_FORMAT(#{createTime}, '%Y-%m-%d')


    and DATE_FORMAT(org.MODIFIED_TIME_, '%Y-%m-%d') like DATE_FORMAT(#{modifiedTime}, '%Y-%m-%d')


    and org.OPERATOR like concat(concat('%',#{operator}),'%')


    and org.is_black like #{isBlack}


    and org.regulator_oth1 = #{regulatorOth1}


    and org.unisc_code like concat(concat('%',#{uniscCode}),'%')


    and org.data_source like #{dataSource}


    and org.mger_org = #{mgerOrg}


    and org.is_subsidiary like #{isSubsidiary}

and org.DELFLAG_ = '1'
ORDER BY MODIFIED_TIME_ DESC

select pid,org_name,identify_type,unisc_code,shareholders_code from bus_rel_org
where 1=1

    and org_name= #{orgName}


    and identify_type= #{identifyType}


    and unisc_code= #{uniscCode}


    and shareholders_code= #{shareholdersCode}

and DELFLAG_=1

select pid,org_name,identify_type,unisc_code,shareholders_code from bus_rel_org_suspect
where 1=1

    and org_name= #{orgName}


    and identify_type= #{identifyType}


    and unisc_code= #{uniscCode}


    and shareholders_code= #{shareholdersCode}

and DELFLAG_=1

select org.*
from bus_rel_org org;
where 1=1

    and org.org_name like #{orgName}


    and org.approval_status like #{approvalStatus}


    and org.identify_type like #{identifyType}


    and org.is_black like #{isBlack}


    and org.regulator_oth1 = #{regulatorOth1}


    and org.unisc_code = #{uniscCode}


    and data_source= #{dataSource}

and org.is_insider = '1' and preset_limit is not null
